import { Component, OnInit } from '@angular/core'; import { ActivatedRoute, Router } from "@angular/router";
import { CWSNService } from "src/app/services/cwsn.service";
import { SqlitedatabaseService } from 'src/app/services/sqlite/sqlitedatabase.service';
import { AlertService } from 'src/app/services/alert.service';
import { HttpClient } from "@angular/common/http";
import { SharedService } from "src/app/services/shared.service";
import { NetworkService } from "src/app/services/network-service";
import { UserSessionService } from 'src/app/services/usersession.service';
import { IonicStorageService } from 'src/app/services/ionic-storage/ionic-storage.service';
