@Component({
  selector: 'app-ca-school-list',
  templateUrl: './ca-school-list.page.html',
  styleUrls: ['./ca-school-list.page.scss'],
})
export class CASchoolListPage implements OnInit {

  routeData: any;
  ZonalId: any;
  partialScreenCount: number = 0;
  totalScreenSchool: number = 0;
  totalNoCWSNStudents: number = 0;
  schoolList: any[] = [];
  schoolListCopy: any;
  searchTerm: any;
  textData: any;
  screenStatus: any;
  unScreenStatus: any;
  noScreeningStatus: any;
  mode: any;
  title: any;
  studentData: any[];
  block_id: any;
  usertype: any;
  user_id: any;
  pipe = new DatePipe("en-US");
  interVenRes = [];

  constructor(
    private router: Router,
    private route: ActivatedRoute,
    private cwsnService: CWSNService,
    private sqliteDB: SqlitedatabaseService,
    private alertService: AlertService,
    private http: HttpClient,
    private ionicstorage: IonicStorageService,
    private userSessionService: UserSessionService,
    private networkService: NetworkService,
    private sharedService: SharedService
  ) { }

  ngOnInit() {

  }

  ionViewDidEnter() {
    this.user_id = this.userSessionService.emis_username();
    this.routeData = this.route.snapshot;
    this.title = this.routeData.queryParams.title;
    this.mode = this.routeData.queryParams.mode;
    this.ionicstorage.getData('getUserDetailsCwsn').then(
      (userData) => {
        this.usertype = userData;
        if (this.usertype == 1) {
          let userDetails = this.sharedService.getUserDetails()
          this.block_id = this.sharedService.TeacherBlockId;
        } else {
          this.block_id = null;
        }
        this.checkLocalDB();
      })
  }

  async checkLocalDB() {
    debugger
    this.schoolList = [];
    let query = 'SELECT * FROM cwsn_ca_stud_list' +
      ' WHERE UserId = "' + this.user_id + '"';
    await this.sqliteDB.executeQuery(query).then(async (res) => {
      if (res.rows.length > 0) {
        let temp = [];
        for (var i = 0; i < res.rows.length; i++) {
          // Object.assign(temp[i], { isChecked: false });
          temp.push(res.rows.item(i));
        };
        let UsertypeTxt = '';
        if (this.usertype == 1) {
          UsertypeTxt = 'SpecialEdu';
        } else {
          UsertypeTxt = 'Therapist';
        }
        let query2 = 'SELECT * FROM fun_assessment_qstns' +
          ' WHERE user_name = "' + UsertypeTxt + '"';
        this.sqliteDB.executeQuery(query2).then(domRes => {
          let temp1 = [];
          for (var i = 0; i < domRes.rows.length; i++) {
            temp1.push(domRes.rows.item(i));
          }
          let domainList = this.domainParse(temp1);
          let query3 = 'SELECT * FROM stud_fun_assessment' +
          ' WHERE user_id = "' + this.user_id + '"';
          this.sqliteDB.executeQuery(query3).then((stdRes) => {
            let assRes = [];
            for (var i = 0; i < stdRes.rows.length; i++) {
              assRes.push(stdRes.rows.item(i));
            };

            let query4 = 'SELECT * FROM stud_int_assessment' +
              ' WHERE user_id = "' + this.user_id + '"';
            this.sqliteDB.executeQuery(query4).then((interRes) => {
              this.interVenRes = [];
              for (var i = 0; i < interRes.rows.length; i++) {
                this.interVenRes.push(interRes.rows.item(i));
              };
              let filteredSchlist = this.calcAssessedStd(temp, assRes, domainList);
              for (let key in filteredSchlist) {
                let obj = {
                  schName: filteredSchlist[key].SchlNme,
                  SchlId: key,
                  status: this.checkSchStatus(filteredSchlist[key].stdList),
                  udise_code: filteredSchlist[key].udise_code
                }
                this.schoolList.push(obj);
              };
              this.schoolListCopy = this.schoolList;
              this.filterScreenUnScreenStudent(this.schoolList);
            });
          });
        });
      } else {
        this.getSchoolList();
      };
    });
  };

  checkSchStatus(stdList = []) {
    let fullyAss = stdList.filter(obj=>{return obj.assStatus==1});
    let partialAss = stdList.filter(obj=>{return obj.assStatus==2});
    let GridStatus = stdList.filter(obj=>{return obj.assStatus==5});
    let totSth= stdList.length;
    let status = '';
    if(fullyAss.length==totSth || GridStatus.length + fullyAss.length == totSth) {
      status = '1';
    } else if((partialAss.length<=totSth && partialAss.length>0||fullyAss.length>0)) {
      status = '2';
    }
    return status;
  }

  checkBox(i, eve, SchlId) {

    let checked_status = 0;
    if (eve.detail.checked == true) {
      checked_status = 1;
    } else {
      if (this.networkService.getCurrentNetworkStatus() == 0) { //online
        checked_status = 0;
        this.schoolList[i].isChecked = false;
      } else { //offline
        checked_status = 1;
        this.schoolList[i].isChecked = true;
        this.alertService.warning('Please check your internet connection');
      }
    };

    let query = 'UPDATE cwsn_ca_schl_list SET checked_status="' + checked_status + '"' +
      'WHERE SchlId = "' + SchlId + '"';
    return this.sqliteDB.update(query).then(res => {
      let chkCnt: any = this.schoolList.filter(obj => {
        return obj.isChecked;
      })
      if (chkCnt.length > 1) {
        for (let i = 0; i < this.schoolList.length; i++) {
          if (!this.schoolList[i].isChecked) {
            this.schoolList[i].isDisable = true;
          }
        }
      } else {
        for (let i = 0; i < this.schoolList.length; i++) {
          if (!this.schoolList[i].isChecked) {
            this.schoolList[i].isDisable = false;
          }
        }
      }
    });
    // }
  }

  getSchoolList() {
    let school_list_json = '';
    if (this.usertype == 1) {
      school_list_json = 'https://d1wpyxz35bzzz4.cloudfront.net/cwsn/CWSN_phase2_student_list_details_' + this.user_id + '_json.json';
      // school_list_json = 'https://d1wpyxz35bzzz4.cloudfront.net/cwsn/CWSN_phase2_student_list_details_' + this.user_id + '_staging_json.json';
    } else {
      school_list_json = 'https://d1wpyxz35bzzz4.cloudfront.net/therapist_' + this.user_id + '_ca_school_list_json.json';
    }
    this.http.get<any>(school_list_json).subscribe((data) => {
      if (data) {
        if (data.length > 0) {
          this.getStudentAssList(data);
        } else {
          this.alertService.warning('No Schools Found');
        }

      } else {
        this.alertService.warning('No Schools Found');
      }
    }, error => {
      this.alertService.warning('No Schools Found');
    })
  }

  goBack() {
    this.router.navigate(['/tabs/cwsn-menu'], { queryParams: { 'mode': this.mode, 'title': this.title } })

    // this.router.navigate(['/tabs/cwsn/ca-school-list'], { queryParams: { 'mode': this.mode, 'title': this.title } })
    // this.router.navigate(['/tabs/cwsn/ca-cluster'], { queryParams: { title: this.title, mode: this.mode, usertype: this.usertype } })
  }

  enSureValueHereOrNot(arr) {
    let value = [];
    arr.map(id => {
      if (id.SchlId !== null && id.SchlId !== undefined && id.SchlId !== '') {
        value = id;
      } else {
        value.length = 0;
      }
    })
    return value;
  }

  filterScreenUnScreenStudent(arr) {
    let screenCount = 0;
    let partialScreenCount = 0;
    let noScreeningCount = 0;

    arr.forEach(element => {
      if (element.status==1) {
        screenCount++;
      }else if (element.status==2) {
        partialScreenCount++;
      }else if (element.status=='') {
        noScreeningCount++;
      }
    });
    this.totalScreenSchool = screenCount;
    this.partialScreenCount = partialScreenCount;
    this.totalNoCWSNStudents = noScreeningCount;
  }

  getSchoolListInSearch(event) {
    this.searchTerm = event.detail.value.trim();
    if (this.schoolListCopy.length > 0) {
      this.schoolList = this.schoolListCopy.filter((item) => {
        return item.schName.toLowerCase().indexOf(this.searchTerm.toLowerCase()) > -1;
      });
    }
  }

  ionViewWillLeave() {
    this.textData = "";
  }


  schoolSelected(item: any) {
    debugger
    this.ionicstorage.insertData_Replace('schlName', item.schName);
    item.mode = this.mode;
    let query = 'SELECT * FROM cwsn_ca_stud_list' +
      ' WHERE SchlId = "' + item.SchlId + '"';
    this.sqliteDB.executeQuery(query).then(async (res) => {
      if (res.rows.length > 0) {
        this.router.navigate(["/tabs/screaning-menu"], { queryParams: { item: JSON.stringify(item), title: this.title, mode: this.mode } });
      } else {
        this.alertService.warning("No data found");
      }
    });
    // }
  }

  inserStdtData(list: any, item) {
    let sqlArray = [];

    list.forEach(element => {
      sqlArray.push(['INSERT INTO cwsn_ca_stud_list (id,SchlId,StuId,name,cwsnStatus,ScrSts,refer_to,scrSts_Local,nid,udid,ScreenedDate,da_name,unique_id_no,isPost,Class,Sec,gender,IndexId,udise_code) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)', [null, element.school_id, element.stdId, element.name, element.referedfrom, element.scrindexid, element.goto, 3, element.nid, element.udid, element.screening_date, element.da_name, element.userId, 3, element.stdCls, element.sec, element.gendr, element.nidIndex,element.udise_code]]);
    });
    this.sqliteDB.bulkInsert(sqlArray).then((insertres) => {
      this.router.navigate(["/tabs/screaning-menu"], { queryParams: { item: JSON.stringify(item), title: this.title, mode: this.mode } });
      // this.router.navigate(['/tabs/ca-student-list'], { queryParams: { item: JSON.stringify(item), 'zonleId': this.ZonalId, title: this.title, mode: this.mode } });
    });
  };

  insertData(list, resData:any) {
    let sqlArray = [];
    let temp  = [];
    let interRes = resData.EvloRes?resData.EvloRes:[];
    let funAss = resData.FuncAsscRes?resData.FuncAsscRes:[];
    funAss.forEach(obj=>{
      let idx = temp.findIndex(obj1=>{return obj1.IndxId== obj.IndxId})
      if(idx!=-1) {
        temp[idx].qstnVal = temp[idx].qstnVal + "," + obj.qstnVal;
      }else {
        temp.push(obj);
      };
    }
  );
  debugger
    interRes.forEach(element => {
      sqlArray.push(['INSERT INTO stud_int_assessment (Id,index_id,user_id,schl_id,stud_id,domain_id,domain_name,subdomain_id,intervension_idx_id,intervention_type_id,rate_val,goal_val,support,date,inter_status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)', [null, element.id, element.user_id, element.school_id, element.student_id, element.domain_id, element.domain_name, element.subdomain_id, element.intervension_idx_id, element.evaluation_type, parseInt(element.rating), element.goal, element.support_in, this.pipe.transform(new Date(), "yyyy-MM-dd"), 2]]);
    });
    temp.forEach(element => {
      sqlArray.push(['INSERT INTO stud_fun_assessment (Id,index_id,user_id,schl_id,stud_id,domain_id,domain_name,subdomain_id,q_id,q_val,date,q_status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)', [null, element.IndxId, element.userId, element.schlId, element.studId, element.domainId, element.domainName, element.subDomainId, element.qstnId, element.qstnVal, this.pipe.transform(new Date(), "yyyy-MM-dd"), 3]]);
    });
    list.forEach(element => {
      if (this.usertype == 2) {
        element.screen = 0;
        sqlArray.push(['INSERT INTO cwsn_ca_stud_list VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)', [null, element.therapist, this.ZonalId, element.block_id, element.school_id, element.school_name, element.student_id, element.name, element.EMIS_No, element.class_studying_id, element.class_section, element.disability_type, element.screen_disability, 0, 0, '1', 0, 0,element.udise_code]]);
      } else {
        sqlArray.push(['INSERT INTO cwsn_ca_stud_list VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)', [null, element.Special_educator, element.zonal_id, element.block_id, element.school_id, element.school_name, element.student_id, element.name, element.EMIS_No, element.class_studying_id, element.class_section, element.disability_type, element.screen_disability, 0, 0, '1', 0, 0,element.udise_code]]);
      }
    });
    this.sqliteDB.bulkInsert(sqlArray).then((insertres) => {
      this.checkLocalDB();
    });
  };

  onSync() {
    let query = 'DELETE FROM cwsn_ca_stud_list';
    this.sqliteDB.executeQuery(query).then(res => {
      if (res) {
        this.checkLocalDB();
      }
    });
  }

  getStudentAssList(jsonData) {
    let schIds = '';
    let schList = [...new Map(jsonData.map(item => [item['school_id'], item])).values()];
    schList.forEach((obj: any) => {
      schIds = schIds ? schIds + "," + obj.school_id : obj.school_id;
    });
    this.cwsnService.GetStudFuncAssessNew(this.user_id, schIds).subscribe(res => {
      if (res.dataStatus) {
        this.insertData(jsonData, res.result);
      } else {
        this.insertData(jsonData, []);
      }
    }, error => {
      this.insertData(jsonData, []);
    });
  }

  domainParse(questionList) {
    var helper = {};
    let domainListArray = questionList.reduce(function (r, o) {
      var key = o.domain_name + '-' + o.domain_id;
      if (!helper[key]) {
        helper[key] = Object.assign({}, o); // create a copy of o
        r.push(helper[key]);
      } else {
        helper[key].disability_type = helper[key].disability_type +","+ o.disability_type;
      }
      return r;
    }, []);
    return domainListArray;
  }

  calcAssessedStd(stdList = [], assRes = [], domainList = []) {
    let schList = {};
    for (let i = 0; i < stdList.length; i++) {
      let assDomains = [];
      let finalDomList = [];

      const srDis = stdList[i].screen_disability.split(',').map(e => +e);
      let filteredStdRes = assRes.filter(obj => { return obj.stud_id == stdList[i].studId });
      for (let j = 0; j < domainList.length; j++) {
        const domDis = domainList[j].disability_type.split(',').map(e => +e);
        let isDisabilityFound = srDis.some(v => domDis.indexOf(v) !== -1);
        if (isDisabilityFound) {
          finalDomList.push(domainList[j]);
        };
        let isDomIn = filteredStdRes.find(o => { return o.domain_id == domainList[j].domain_id });
        if (isDomIn) {
          assDomains.push(domainList[j]);
        }
      };
     
      // inga tha green pannanum
      stdList[i].assStatus = this.assessLvl(finalDomList, assDomains,stdList[i].studId,this.interVenRes);
      const srDis2 = stdList[i].screen_disability.split(',').map(e => e.trim());
      const arr = ["6", "18", "19", "20", "21", "22"];

      const allValid = srDis2.every(val => arr.includes(val));
      if (srDis2.length > 0 && allValid) {
        stdList[i].assStatus = 5;
      }
      schList[stdList[i].SchlId] = schList[stdList[i].SchlId] ? schList[stdList[i].SchlId] : {};
      schList[stdList[i].SchlId].SchlNme = stdList[i].SchlNme;
      schList[stdList[i].SchlId].udise_code = stdList[i].udise_code;
      schList[stdList[i].SchlId].stdList=schList[stdList[i].SchlId].stdList?schList[stdList[i].SchlId].stdList:[];
      schList[stdList[i].SchlId].stdList.push(stdList[i]);
    };
    return schList;
  }

  assessLvl(domList = [], assList = [],stdId,interRes=[]) {
    let idx = interRes.findIndex(obj=>{return obj.stud_id == stdId});
    let a = domList.length, b = assList.length;
    let status = '';
    if ((a == b)&&(a&&b)) {
      if(idx!=-1) {
        status = "1";
      }else {
        status = "2";
      }
    } else if (a > b && b > 0) {
      status = "2";
    }
    return status;
  }

}
